69	void do_net_send(uintptr_t addr, size_t length)
70	{
71	    // send all packet
72	    send_transaction = 1;
73	    enable_sum();
74	    memset(&tx_buffer, 0, sizeof(EthernetFrame));
75	    memcpy((uint8_t*)&tx_buffer, (uint8_t*)addr, length);
76	    EmacPsSend(&EmacPsInstance, 0, length);
77	    if(net_poll_mode == 0){
78	        EmacPsWaitSend(&EmacPsInstance);
79	        send_transaction = 0;
80	    }
81	    else if(net_poll_mode == 1){
82	        do_block(&current_running[cpu_id]->list, &net_send_queue);
83	        scheduler();
84	    }
85	    disable_sum();
