43	    pcb_t *prev_running = current_running[cpu_id];
44	
45	    /* put the current process back into the ready queue if it is
46	     * still runnable; the kernel idle processes (pid 0) are never queued */
47	    if(prev_running->status == TASK_RUNNING && prev_running->pid != 0){
48	        prev_running->status = TASK_READY;
49	        prev_running->ready_tick = get_ticks();
50	        list_add_tail(&prev_running->list, &ready_queue);
51	    }
52	
53	    /* pick the highest priority process that may run on this core */
54	    list_node_t *next_node = max_priority_node();
55	    pcb_t *next_running;
56	    if(next_node == NULL){
57	        next_running = (pcb_t*)(cpu_id == 0 ? core0_tp : core1_tp);
58	    }
59	    else{
60	        list_del(next_node);
61	        next_running = list_entry(next_node, pcb_t, list);
62	    }
63	
64	    next_running->status = TASK_RUNNING;
65	    next_running->cpu_id = cpu_id;
66	    current_running[cpu_id] = next_running;
67	    current_cpu_running = next_running;
68	
69	    /* switch the address space (pgdir is pa) */
70	    set_satp(SATP_MODE_SV39, 0, ((uintptr_t)next_running->pgdir) >> NORMAL_PAGE_SHIFT);
71	    local_flush_tlb_all();
72	}
