74	pid_t do_exec(const char* file_name, int argc, char* argv[], spawn_mode_t mode)
75	{
76	    // file_name and argv live in the caller's address space
77	    enable_sum();
78	
79	    /* look up the elf file embedded in the kernel image */
80	    unsigned char *binary;
81	    int length;
82	    if(get_elf_file(file_name, &binary, &length) == 0){
83	        disable_sum();
84	        return -1;
85	    }
86	
87	    /* find a free pcb */
88	    int i;
89	    for(i = 0; i < NUM_MAX_TASK; i++){
90	        if(pcb[i].pid == -1){
91	            break;
92	        }
93	    }
94	    if(i == NUM_MAX_TASK){
95	        disable_sum();
96	        return 0;
97	    }
98	
99	    /* initialize the pcb */
100	    pcb[i].kernel_sp = pa2kva(alloc_user_page(1, NULL) + PAGE_SIZE);
101	    pcb[i].user_sp = USER_STACK_ADDR;
102	    pcb[i].preempt_count = 0;
103	    pcb[i].kernel_stack_base = pcb[i].kernel_sp;
104	    pcb[i].user_stack_base = pcb[i].user_sp;
105	    init_list_head(&pcb[i].wait_list);
106	    pcb[i].binsem_num = 0;
107	    pcb[i].pid = process_id++;
108	    pcb[i].type = USER_PROCESS;
109	    pcb[i].status = TASK_READY;
110	    pcb[i].mode = mode;
111	    pcb[i].priority = 0;
112	    pcb[i].ready_tick = get_ticks();
113	    pcb[i].mask = 3;
114	    pcb[i].cursor_x = 0;
115	    pcb[i].cursor_y = 0;
116	    pcb[i].pgdir = init_page_table();
117	
118	    /* load the elf into the fresh address space */
119	    uintptr_t entry = load_elf(binary, length, (uintptr_t)pcb[i].pgdir, alloc_page_helper);
120	
121	    /* copy argc/argv onto the new user stack */
122	    int total_len = 0;
123	    for(int j = 0; j < argc; j++){
124	        total_len += strlen(argv[j]) + 1;
125	    }
126	    uintptr_t argv_base = ROUNDDOWN(USER_STACK_ADDR - total_len, sizeof(uintptr_t)) - argc * sizeof(uintptr_t);
127	    uintptr_t str_sp = USER_STACK_ADDR;
128	    for(int j = 0; j < argc; j++){
129	        str_sp -= strlen(argv[j]) + 1;
130	        strcpy((char*)get_kva_of(str_sp, (uintptr_t)pcb[i].pgdir), argv[j]);
131	        *(uintptr_t*)get_kva_of(argv_base + j * sizeof(uintptr_t), (uintptr_t)pcb[i].pgdir) = str_sp;
132	    }
133	    pcb[i].user_sp = ROUNDDOWN(argv_base, 16);
134	
135	    /* initialize the trap frame so the first schedule enters at the elf entry */
136	    regs_context_t *pt_regs = (regs_context_t *)(pcb[i].kernel_sp - sizeof(regs_context_t));
137	    pcb[i].kernel_sp -= sizeof(regs_context_t);
138	    pt_regs->regs[1] = (reg_t)entry;                // ra
139	    pt_regs->regs[2] = (reg_t)pcb[i].user_sp;       // sp
140	    pt_regs->regs[3] = (reg_t)__global_pointer$;    // gp
141	    pt_regs->regs[10] = (reg_t)argc;                // a0
142	    pt_regs->regs[11] = (reg_t)argv_base;           // a1
143	    pt_regs->sstatus = (reg_t)SR_SPIE;              // SPP = 0, SPIE = 1
144	    pt_regs->sepc = (reg_t)entry;                   // sepc
145	    pt_regs->sscratch = (reg_t)&pcb[i];             // sscratch = tp
146	
147	    list_add_tail(&pcb[i].list, &ready_queue);
148	
149	    disable_sum();
150	    return pcb[i].pid;
151	}
