153	// release all the binary semaphores held by p, waking up blocked processes
154	static void release_all_binsem(pcb_t *p)
155	{
156	    while(p->binsem_num > 0){
157	        int binsem_id = p->binsem_id[p->binsem_num - 1];
158	        binsem_node_t *node = &binsem_nodes[binsem_id];
159	        node->sem++;
160	        p->binsem_num--;
161	        if(node->sem <= 0){
162	            // hand the semaphore over to the first blocked process
163	            list_node_t *unblocked_node = node->block_queue.next;
164	            pcb_t *unblocked_pcb = list_entry(unblocked_node, pcb_t, list);
165	            unblocked_pcb->binsem_id[unblocked_pcb->binsem_num] = binsem_id;
166	            unblocked_pcb->binsem_num++;
167	            do_unblock(unblocked_node);
168	        }
169	    }
170	}
