172	void do_exit()
173	{
174	    pcb_t *exit_pcb = current_running[cpu_id];
175	
176	    // release all the binary semaphores this process holds
177	    release_all_binsem(exit_pcb);
178	
179	    // wake up the processes waiting for this process
180	    while(!list_empty(&exit_pcb->wait_list)){
181	        do_unblock(exit_pcb->wait_list.next);
182	    }
183	
184	    if(exit_pcb->mode == ENTER_ZOMBIE_ON_EXIT){
185	        // become a zombie until someone waits for us;
186	        // the vm resources are released later by do_waitpid
187	        exit_pcb->status = TASK_ZOMBIE;
188	    }
189	    else{
190	        // AUTO_CLEANUP_ON_EXIT: release the vm resources now and
191	        // let the kernel idle loop recycle the pcb and kernel stack
192	        free_process_user_page(exit_pcb->pgdir);
193	        free_pgdir_page((uintptr_t)exit_pcb->pgdir);
194	        exit_pcb->pgdir = NULL;
195	        exit_pcb->status = TASK_ZOMBIE;
196	        list_add_tail(&exit_pcb->list, &kernel_pcb[0].wait_list);
197	    }
198	
199	    scheduler();
200	}
