214	int do_kill(pid_t pid)
215	{
216	    // killing itself is equivalent to exit
217	    if(pid == current_running[cpu_id]->pid){
218	        do_exit();
219	        return 1;
220	    }
221	
222	    // search the pcb
223	    pcb_t *kill_pcb = NULL;
224	    for(int i = 0; i < NUM_MAX_TASK; i++){
225	        if(pcb[i].pid == pid){
226	            kill_pcb = &pcb[i];
227	            break;
228	        }
229	    }
230	    if(kill_pcb == NULL || kill_pcb->status == TASK_ZOMBIE || kill_pcb->status == TASK_EXITED){
231	        return 0;
232	    }
233	
234	    // release the binary semaphores it holds
235	    release_all_binsem(kill_pcb);
236	
237	    // wake up the processes waiting for it
238	    while(!list_empty(&kill_pcb->wait_list)){
239	        do_unblock(kill_pcb->wait_list.next);
240	    }
241	
242	    // remove it from whatever queue it is in
243	    list_del(&kill_pcb->list);
244	
245	    // release the vm resources
246	    free_process_user_page(kill_pcb->pgdir);
247	    free_pgdir_page((uintptr_t)kill_pcb->pgdir);
248	    kill_pcb->pgdir = NULL;
249	
250	    // let the kernel idle loop recycle the pcb and kernel stack
251	    kill_pcb->status = TASK_ZOMBIE;
252	    list_add_tail(&kill_pcb->list, &kernel_pcb[0].wait_list);
253	
254	    return 1;
255	}
