257	int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, reg_t ignore3, regs_context_t *regs)
258	{
259	    // search the pcb
260	    pcb_t *wait_pcb = NULL;
261	    for(int i = 0; i < NUM_MAX_TASK; i++){
262	        if(pcb[i].pid == pid){
263	            wait_pcb = &pcb[i];
264	            break;
265	        }
266	    }
267	    if(wait_pcb == NULL || wait_pcb->status == TASK_EXITED){
268	        return 0;
269	    }
270	
271	    if(wait_pcb->status != TASK_ZOMBIE){
272	        // block until the target process exits
273	        do_block(&current_running[cpu_id]->list, &wait_pcb->wait_list);
274	        scheduler();
275	    }
276	
277	    // recycle the zombie: release its vm resources (unless they were
278	    // already released by an AUTO_CLEANUP_ON_EXIT do_exit/do_kill) and
279	    // hand the pcb and kernel stack to the kernel idle loop
280	    if(wait_pcb->pgdir != NULL){
281	        free_process_user_page(wait_pcb->pgdir);
282	        free_pgdir_page((uintptr_t)wait_pcb->pgdir);
283	        wait_pcb->pgdir = NULL;
284	        list_del(&wait_pcb->list);
285	        list_add_tail(&wait_pcb->list, &kernel_pcb[0].wait_list);
286	    }
287	
288	    return pid;
289	}
