459	// block the pcb task into the block queue
460	void do_block(list_node_t *pcb_node, list_head *queue)
461	{
462	    list_del(pcb_node);
463	    list_add_tail(pcb_node, queue);
464	    list_entry(pcb_node, pcb_t, list)->status = TASK_BLOCKED;
465	}
