467	// unblock the `pcb` from the block queue
468	void do_unblock(list_node_t *pcb_node)
469	{
470	    list_del(pcb_node);
471	    list_add_tail(pcb_node, &ready_queue);
472	    list_entry(pcb_node, pcb_t, list)->status = TASK_READY;
473	    list_entry(pcb_node, pcb_t, list)->ready_tick = get_ticks();
474	}
