476	list_node_t* max_priority_node(void)
477	{
478	    list_node_t *node = ready_queue.next;
479	    list_node_t *max_node = NULL;
480	    while(node != &ready_queue){
481	        pcb_t *p = list_entry(node, pcb_t, list);
482	        // skip dead processes and processes pinned to the other core
483	        if(p->pgdir != NULL && (p->mask & (1lu << cpu_id))){
484	            if(max_node == NULL){
485	                max_node = node;
486	            }
487	            else{
488	                pcb_t *max_pcb = list_entry(max_node, pcb_t, list);
489	                // higher priority first; break ties by the earliest ready_tick
490	                if(p->priority > max_pcb->priority ||
491	                   (p->priority == max_pcb->priority && p->ready_tick < max_pcb->ready_tick)){
492	                    max_node = node;
493	                }
494	            }
495	        }
496	        node = node->next;
497	    }
498	    return max_node;
499	}

