51	ptr_t alloc_user_page(uint8_t pin, PTE* pgtable)
52	{
53	    int i;
54	    for(i = 0; i < USER_PAGE_NUM; i++){
55	        if(user_page[i].valid == 0){
56	            break;
57	        }
58	    }
59	    if(i == USER_PAGE_NUM){
60	        // no free user page: swap out a victim page to sd
61	        ptr_t victim_pa = selete_page();
62	        write_to_sd(victim_pa);
63	        i = pa2num(victim_pa);
64	    }
65	    user_page[i].valid = 1;
66	    user_page[i].pin = pin;
67	    user_page[i].pgtable = pgtable;
68	    return num2pa(i);
69	}
