86	// select a user page to write to disk (NRU), returns pa
87	ptr_t selete_page()
88	{
89	    int i;
90	    // first round: pick a valid unpinned page whose A bit is 0,
91	    // clearing the A bit of the pages we skip (second chance)
92	    for(i = 0; i < USER_PAGE_NUM; i++){
93	        if(user_page[i].valid && !user_page[i].pin){
94	            PTE *pte = user_page[i].pgtable;
95	            if(pte != NULL && get_attribute(*pte, _PAGE_ACCESSED)){
96	                clear_attribute(pte, _PAGE_ACCESSED);
97	            }
98	            else{
99	                return num2pa(i);
100	            }
101	        }
102	    }
103	    // second round: all A bits were cleared, pick the first victim
104	    for(i = 0; i < USER_PAGE_NUM; i++){
105	        if(user_page[i].valid && !user_page[i].pin){
106	            return num2pa(i);
107	        }
108	    }
109	    // every user page is pinned: should not happen
110	    assert(0);
111	    return 0;
112	}
113	
114	void write_to_sd(ptr_t pa)
115	{
116	    // find a free swap slot on sd
117	    int i;
118	    for(i = 0; i < DISK_PAGE_NUM; i++){
119	        if(disk_page[i].valid == 0){
120	            break;
121	        }
122	    }
123	    assert(i != DISK_PAGE_NUM);
124	    disk_page[i].valid = 1;
125	
126	    // a page occupies PAGE_SIZE / 512 blocks, swap area starts at SWAP_BEGIN
127	    sbi_sd_write(pa, PAGE_SIZE / 512, SWAP_BEGIN + i * (PAGE_SIZE / 512));
128	
129	    // mark the owner's PTE as swapped out: !PRESENT, SOFT set,
130	    // and record the swap slot index in the pfn field
131	    int num = pa2num(pa);
132	    PTE *pte = user_page[num].pgtable;
133	    if(pte != NULL){
134	        clear_attribute(pte, _PAGE_PRESENT);
135	        set_attribute(pte, _PAGE_SOFT);
136	        set_pfn(pte, i);
137	    }
138	
139	    user_page[num].valid = 0;
140	    local_flush_tlb_all();
141	}
