143	unsigned long free_page_num()
144	{
145	    unsigned long ret = 0;
146	    for(int i = 0; i < USER_PAGE_NUM; i++){
147	        if(user_page[i].valid == 0){
148	            ret++;
149	        }
150	    }
151	    return ret;
152	}
