154	/*
155	 * Virtual Memory Layout
156	 * 0x0_0000_1000 ~ 0x0_0001_0000: share
157	 * 0x0_0001_0000 ~ 0x0_0001_3000: code
158	 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
159	 */
160	PTE* init_page_table()
161	{
162	    // allocate a fresh top level page table, returns pa
163	    PTE *pgdir = alloc_pgdir_page();
164	    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
165	    PTE *boot_pgdir_kva = (PTE*)pa2kva(PGDIR_PA);
166	
167	    /*
168	     * share the kernel mappings with the boot page table:
169	     * entry 0x001: identity map of 0x5000_0000 ~ 0x6000_0000 (large pages)
170	     * entry 0x101: kernel virtual map (large pages)
171	     * both point to the shared second level table at PGDIR_PA + PAGE_SIZE,
172	     * so trap handling and kernel code stay reachable under every satp
173	     */
174	    pgdir_kva[0x001] = boot_pgdir_kva[0x001];
175	    pgdir_kva[0x101] = boot_pgdir_kva[0x101];
176	
177	    // map one page for the user stack: [USER_STACK_ADDR - PAGE_SIZE, USER_STACK_ADDR)
178	    alloc_page_helper(USER_STACK_ADDR - PAGE_SIZE, (uintptr_t)pgdir);
179	
180	    return pgdir;
181	}
182	
183	void free_process_user_page(PTE* pgdir)
184	{
185	    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
186	    for(int VPN2 = 0; VPN2 < NUM_PTE_ENTRY; VPN2++){
187	        // entries 0x001/0x101 reference the shared kernel table: never touch
188	        if(VPN2 == 0x001 || VPN2 == 0x101){
189	            continue;
190	        }
191	        if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
192	            continue;
193	        }
194	        PTE *second_level_pgdir = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
195	        for(int VPN1 = 0; VPN1 < NUM_PTE_ENTRY; VPN1++){
196	            if(!get_attribute(second_level_pgdir[VPN1], _PAGE_PRESENT)){
197	                continue;
198	            }
199	            PTE *last_level_pgdir = (PTE*)pa2kva(get_pa(second_level_pgdir[VPN1]));
200	            for(int VPN0 = 0; VPN0 < NUM_PTE_ENTRY; VPN0++){
201	                PTE entry = last_level_pgdir[VPN0];
202	                if(get_attribute(entry, _PAGE_PRESENT)){
203	                    uintptr_t pa = get_pa(entry);
204	                    // a shared memory page is only released when its
205	                    // reference count drops to zero
206	                    int is_shm = 0;
207	                    for(int i = 0; i < SHM_PAGE_NUM; i++){
208	                        if(shm_page[i].count > 0 && shm_page[i].pa == pa){
209	                            shm_page[i].count--;
210	                            if(shm_page[i].count == 0){
211	                                free_user_page(pa);
212	                            }
213	                            is_shm = 1;
214	                            break;
215	                        }
216	                    }
217	                    if(!is_shm){
218	                        free_user_page(pa);
219	                    }
220	                }
221	                else if(get_attribute(entry, _PAGE_SOFT)){
222	                    // swapped out page: release its swap slot on sd
223	                    disk_page[get_pfn(entry)].valid = 0;
224	                }
225	            }
226	            // free the last level page table itself
227	            free_pgdir_page(get_pa(second_level_pgdir[VPN1]));
228	        }
229	        // free the second level page table itself
230	        free_pgdir_page(get_pa(pgdir_kva[VPN2]));
231	    }
232	    local_flush_tlb_all();
233	}
234	
235	// pgdir is pa. if va is not mapped, then mapped it
236	uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
237	{
238	    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
239	    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
240	    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
241	
242	    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
243	    if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
244	        PTE *second_level_pgdir = alloc_pgdir_page();
245	        set_pfn(&pgdir_kva[VPN2], (uintptr_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
246	        set_attribute(&pgdir_kva[VPN2], _PAGE_PRESENT);
247	    }
248	
249	    PTE *second_level_pgdir = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
250	    if(!get_attribute(second_level_pgdir[VPN1], _PAGE_PRESENT)){
251	        PTE *last_level_pgdir = alloc_pgdir_page();
252	        set_pfn(&second_level_pgdir[VPN1], (uintptr_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
253	        set_attribute(&second_level_pgdir[VPN1], _PAGE_PRESENT);
254	    }
255	
256	    PTE *last_level_pgdir = (PTE*)pa2kva(get_pa(second_level_pgdir[VPN1]));
257	    if(!get_attribute(last_level_pgdir[VPN0], _PAGE_PRESENT)){
258	        ptr_t pa = alloc_user_page(0, &last_level_pgdir[VPN0]);
259	        set_pfn(&last_level_pgdir[VPN0], pa >> NORMAL_PAGE_SHIFT);
260	        set_attribute(&last_level_pgdir[VPN0], _PAGE_PRESENT);
261	        set_attribute(&last_level_pgdir[VPN0], _PAGE_READ);
262	        set_attribute(&last_level_pgdir[VPN0], _PAGE_WRITE);
263	        set_attribute(&last_level_pgdir[VPN0], _PAGE_EXEC);
264	        set_attribute(&last_level_pgdir[VPN0], _PAGE_USER);
265	        set_attribute(&last_level_pgdir[VPN0], _PAGE_ACCESSED);
266	        set_attribute(&last_level_pgdir[VPN0], _PAGE_DIRTY);
267	    }
268	
269	    return pa2kva(get_pa(last_level_pgdir[VPN0])) | (va & PAGE_OFFSET_MASK);
270	}
271	
272	// walk pgdir (pa) for va, returns the kva of the leaf level PTE,
273	// or NULL if any intermediate level is missing
274	static PTE* walk_pgdir(uintptr_t va, uintptr_t pgdir)
275	{
276	    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
277	    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
278	    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
279	
280	    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
281	    if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
282	        return NULL;
283	    }
284	    PTE *second_level_pgdir = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
285	    if(!get_attribute(second_level_pgdir[VPN1], _PAGE_PRESENT)){
286	        return NULL;
287	    }
288	    PTE *last_level_pgdir = (PTE*)pa2kva(get_pa(second_level_pgdir[VPN1]));
289	    return &last_level_pgdir[VPN0];
290	}
291	
292	// same as walk_pgdir, but allocate the missing intermediate levels
293	static PTE* walk_pgdir_alloc(uintptr_t va, uintptr_t pgdir)
294	{
295	    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
296	    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
297	    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
298	
299	    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
300	    if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
301	        PTE *second_level_pgdir = alloc_pgdir_page();
302	        set_pfn(&pgdir_kva[VPN2], (uintptr_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
303	        set_attribute(&pgdir_kva[VPN2], _PAGE_PRESENT);
304	    }
305	    PTE *second_level_pgdir = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
306	    if(!get_attribute(second_level_pgdir[VPN1], _PAGE_PRESENT)){
307	        PTE *last_level_pgdir = alloc_pgdir_page();
308	        set_pfn(&second_level_pgdir[VPN1], (uintptr_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
309	        set_attribute(&second_level_pgdir[VPN1], _PAGE_PRESENT);
310	    }
311	    PTE *last_level_pgdir = (PTE*)pa2kva(get_pa(second_level_pgdir[VPN1]));
312	    return &last_level_pgdir[VPN0];
313	}
