315	uintptr_t shm_page_get(int key)
316	{
317	    int i = key % SHM_PAGE_NUM;
318	    // shared pages are mapped in the share area, one page per key
319	    uintptr_t va = 0x1000lu + i * PAGE_SIZE;
320	    pcb_t *cur = current_running[cpu_id];
321	
322	    if(shm_page[i].count == 0){
323	        // first process getting this page: allocate a pinned page and zero it
324	        uintptr_t pa = alloc_user_page(1, NULL);
325	        memset((void*)pa2kva(pa), 0, PAGE_SIZE);
326	        shm_page[i].pa = pa;
327	        shm_page[i].count = 1;
328	    }
329	    else{
330	        shm_page[i].count++;
331	    }
332	
333	    // map the shared physical page into the current address space
334	    PTE *pte = walk_pgdir_alloc(va, (uintptr_t)cur->pgdir);
335	    set_pfn(pte, shm_page[i].pa >> NORMAL_PAGE_SHIFT);
336	    set_attribute(pte, _PAGE_PRESENT);
337	    set_attribute(pte, _PAGE_READ);
338	    set_attribute(pte, _PAGE_WRITE);
339	    set_attribute(pte, _PAGE_USER);
340	    set_attribute(pte, _PAGE_ACCESSED);
341	    set_attribute(pte, _PAGE_DIRTY);
342	    local_flush_tlb_all();
343	
344	    return va;
345	}
346	
347	void shm_page_dt(uintptr_t addr)
348	{
349	    pcb_t *cur = current_running[cpu_id];
350	    PTE *pte = walk_pgdir(addr, (uintptr_t)cur->pgdir);
351	    if(pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)){
352	        return;
353	    }
354	
355	    uintptr_t pa = get_pa(*pte);
356	    for(int i = 0; i < SHM_PAGE_NUM; i++){
357	        if(shm_page[i].count > 0 && shm_page[i].pa == pa){
358	            shm_page[i].count--;
359	            if(shm_page[i].count == 0){
360	                free_user_page(pa);
361	            }
362	            break;
363	        }
364	    }
365	
366	    // unmap the page from the current address space
367	    *pte = 0;
368	    local_flush_tlb_all();
369	}
