371	void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
372	{
373	    pcb_t *cur = current_running[cpu_id];
374	    uintptr_t va = stval;
375	    PTE *pte = walk_pgdir(va, (uintptr_t)cur->pgdir);
376	
377	    if(pte != NULL && get_attribute(*pte, _PAGE_SOFT)){
378	        // the page was swapped out to sd: swap it back in
379	        int slot = get_pfn(*pte);
380	        ptr_t pa = alloc_user_page(0, pte);
381	        sbi_sd_read(pa, PAGE_SIZE / 512, SWAP_BEGIN + slot * (PAGE_SIZE / 512));
382	        disk_page[slot].valid = 0;
383	
384	        clear_attribute(pte, _PAGE_SOFT);
385	        set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
386	        set_attribute(pte, _PAGE_PRESENT);
387	        set_attribute(pte, _PAGE_ACCESSED);
388	    }
389	    else if(pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)){
390	        // the page has never been mapped: demand paging
391	        alloc_page_helper(va, (uintptr_t)cur->pgdir);
392	    }
393	    local_flush_tlb_all();
394	}
